-- Optional Oracle 21c+ fixture for the native JSON datatype.
-- Run only on versions that support JSON as a SQL data type.

SET DEFINE OFF
SET SQLBLANKLINES ON
WHENEVER SQLERROR EXIT SQL.SQLCODE

BEGIN
  EXECUTE IMMEDIATE 'DROP TABLE OC_21C_JSON_DOCS CASCADE CONSTRAINTS';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -942 THEN RAISE; END IF;
END;
/

CREATE TABLE OC_21C_JSON_DOCS (
  DOC_ID NUMBER(10) NOT NULL,
  DOC_BODY JSON,
  CREATED_AT DATE DEFAULT SYSDATE NOT NULL,
  CONSTRAINT OC_21C_JSON_DOCS_PK PRIMARY KEY (DOC_ID)
);

COMMENT ON TABLE OC_21C_JSON_DOCS IS '21c JSON datatype fixture for oracode';

PROMPT Optional 21c JSON fixture loaded
